// Generated by scripts/measure-company-logos.mjs from the 60 portfolio sources.
// Bounds use alpha >= 16/255 at up to 1600px; original assets are untouched.

export type CompanyLogoMetric = {
  name: string;
  intrinsicWidth: number;
  intrinsicHeight: number;
  /** Visible source bounds in intrinsic pixels; opaque tiles include their background. */
  inkBounds: { x: number; y: number; width: number; height: number };
  /** Source-space crop fractions, each between zero and one. */
  crop: { left: number; top: number; width: number; height: number };
  inkAspect: number;
  kind: "icon" | "wordmark";
  label?: string;
  tone: "dark" | "light" | "mixed";
  meanLuminance: number;
  /** Alpha-weighted coverage inside the visible bounds, for optical area sizing. */
  inkCoverage: number;
  visibleCoverage: number;
  opticalBoost: number;
  stacked?: boolean;
  /** These sources cannot be recolored using their alpha mask alone. */
  bakedBackground?: "dark-tile" | "light-checkerboard";
};

