export function getCompanyLogoMetrics(source: string): CompanyLogoMetric | undefined {
  const pathname = source.split(/[?#]/, 1)[0];
  return Object.prototype.hasOwnProperty.call(COMPANY_LOGO_METRICS, pathname)
    ? COMPANY_LOGO_METRICS[pathname]
    : undefined;
}
